                            ["name"] = "Baandari Pedlar Guar",
                            ["id"] = 6184,
                            ["furnitureId"] = 5963,
                            ["description"] = "For years, the Baandari Pedlars have traveled hither and yon, requiring them to train and equip mounts for both comfort and utility. Now you too can ride a colorful guar mount that has that Baandari style!",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mounticon_guarbandaari.dds",
                        },
                        [6185] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Baandari Pedlar Senche-Lion",
                            ["id"] = 6185,
                            ["furnitureId"] = 5902,
                            ["description"] = "Prone to rumbles and purrs, the Baandari Pedlar Senche-Lion serves as both a mount and a source of warmth on cold evenings around the campfire. Just watch out for that rasping tongue.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_baandaripedsenche.dds",
                        },
                        [6186] = 
