                            ["name"] = "Pedlar Pack Pony",
                            ["id"] = 6187,
                            ["furnitureId"] = 5876,
                            ["description"] = "In their travels, the Baandari Pedlars have shown off their pack ponies to the delight of children everywhere. Recently they began selling them, and now children put even more pressure on parents to acquire them.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/bandaaripedlarpony.dds",
                        },
                        [6188] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Pedlar Pack Wolf Cub",
                            ["id"] = 6188,
                            ["furnitureId"] = 5877,
                            ["description"] = "Even the pups receive the full Baandari Pedlar tack treatment! These wolf cubs are often seen chasing each other around those seeking wares from the Pedlars, sometimes tripping up customers until they're trained to know better.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_pedlarwolfcub.dds",
