                            ["category"] = "Exotic",
                            ["name"] = "Pedlar Pack Spider",
                            ["id"] = 6189,
                            ["furnitureId"] = 5878,
                            ["description"] = "The Baandari Pedlars first used these repurposed mechanized spiders to help retrieve things that got lost in crevices and the like. For the right price, they may sell you one.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pets_baandaripedlarspider.dds",
                        },
