                        },
                        [67] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Amber Ash Hopper",
                            ["id"] = 67,
                            ["furnitureId"] = 4175,
                            ["description"] = "Native to the upper Ashlands and the slopes of Red Mountain, the perky Amber Ash Hopper is a favorite pet of Dunmer expatriates, as it's relatively low maintenance (it digs its own hole in the ground), and it reminds the Dark Elves of home.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_118.dds",
                        },
                        [68] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Deep-Moss Ash Hopper",
                            ["id"] = 68,
                            ["furnitureId"] = 4176,
                            ["description"] = "The Deep-Moss Ash Hopper is native to southern Vvardenfell, where it's most commonly found in the fungal-forested uplands and the coastal marshes. They've been adopted as mascot bugs by the Buoyant Armigers, who admire their green carapaces.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_125.dds",
                        },
                        [69] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Ruby Shroom Shalk",
                            ["id"] = 69,
                            ["furnitureId"] = 4177,
                            ["description"] = "The Ruby Shroom Shalk is a popular house pet on the Telvanni Coast; the sway of its warm red fungus caps as it waddles about in the firelight of a parlor hearth just says \"I'm home\" to Dark Elves of a sentimental nature.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_133.dds",
                        },
                        [10311] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Highland Spotted Lynx Cub",
                            ["id"] = 10311,
                            ["furnitureId"] = 8351,
                            ["description"] = "Years ago, vermin overran Kvatch during a poor harvest year. To combat this threat to their low winter food supplies, the citizens brought in spotted lynx cubs from breeders. These creatures love freshly hunted vermin, warm hearths, and crusty bread.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_kvatchspottedlynxcub.dds",
                        },
                        [10312] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Highland Spotted Lynx",
                            ["id"] = 10312,
                            ["furnitureId"] = 8352,
                            ["description"] = "This spotted lynx was an uncommon sight in the Colovian hills until an enterprising hunter brought back some young to raise. Decades later, these lithe creatures serve well as mounts to those who prefer felines.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_kvatchspottedlynx.dds",
                        },
                        [10313] = 
