                            ["category"] = "Flying Pets",
                            ["name"] = "Dockside Paper Wasp",
                            ["id"] = 10313,
                            ["furnitureId"] = 8366,
                            ["description"] = "\"Clearing wasps from the Betnikh docks falls to our youngest warrior. One such asked a mage to help her befriend the wasps, and she led them away. All but one settled elsewhere, instead choosing to follow her loyally. I see you have one now.\"—Stulga",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_wasp.dds",
                        },
                        [10316] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Autumnal Indrik",
                            ["id"] = 10316,
                            ["furnitureId"] = 8367,
                            ["description"] = "As the weather chills and leaves take on fiery hues, the spirit of this young indrik begins to stir. When a paladin of Jephre performs an act the God of Song and Forest finds worthy, it takes its shaky steps into the world.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_harvestfireindrik.dds",
                        },
                        [77] = 
                        {
