                            ["name"] = "Blue-Cap Shroom Shalk",
                            ["id"] = 77,
                            ["furnitureId"] = 4178,
                            ["description"] = "For the Dark Elves, the Shroom Shalk is a companion animal that brings calm and serenity to the Dunmeri home. There's just something so soothing about the way the blue fungal sprouts on its back gently wave and puff out spores as the beast putters about.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_122.dds",
                        },
                        [78] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Bitter Coast Cliff Strider",
                            ["id"] = 78,
                            ["furnitureId"] = 4179,
                            ["description"] = "Thetys Ramarys of Balmora says, \"I love our Bitter Coast Striders, but feel bad that they can't fly very well. So I'm selectively breeding them into a strain that, one day, will dominate the Vvardenfell skies, pursuing its prey for great distances!\"",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_121.dds",
                        },
                        [10319] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Piebald Cat",
                            ["id"] = 10319,
                            ["furnitureId"] = 8380,
                            ["description"] = "Bretons have a strange practice of letting piebald cats loose in the secret passages of their manor homes. It stems from an ancient, noisy infestation of Sheogorath's never-there beetles. It took years, but the clever felines eventually killed them all.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_piebaldcat.dds",
                        },
                        [10320] = 
                        {
