                        [6929] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Sable Tenmar Stray",
                            ["id"] = 6929,
                            ["furnitureId"] = 6503,
                            ["description"] = "Originally bred by Tenmar Khajiit, these wily strays made their way to Senchal and now roam several port cities. Captains love having them on board ships to sniff out and kill vermin, plus help keep the crew warm on cold nights at sea.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_stabletenmarstray.dds",
                        },
                        [6930] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Merle Paddock Hound",
                            ["id"] = 6930,
                            ["furnitureId"] = 6504,
                            ["description"] = "\"Some say that dogs of this breed don't have a mean bone in their bodies, but if you set them up to guard horses or other creatures, you'll see one fierce guardian. Also great at rounding up livestock.\"—Piet",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_merlepaddockhound.dds",
                        },
                        [6942] = 
                        {
                            ["category"] = "Cervines",
                            ["name"] = "Spectral Indrik",
                            ["id"] = 6942,
                            ["furnitureId"] = 6506,
                            ["description"] = "Rare indriks don't die but instead live on as haunting apparitions. Though they walk between two worlds, these ghostly steeds serve their chosen companions well as mounts. Some Summerset High Elves claim this is a true sign of a rider's worthiness.",
                            ["hint"] = "Obtained by combining four different Spectral Berries with a Nascent Indrik mount. The Nascent Indrik will become the Spectral Indrik.",
                            ["icon"] = "/esoui/art/icons/mount_spectralindrik.dds",
                        },
                        [13089] = 
                        {
                            ["category"] = "General",
                            ["name"] = "Statuette: Yokudan War-Scholar",
                            ["id"] = 13089,
                            ["furnitureId"] = 10380,
                            ["description"] = "Brilliant battlefield tacticians often became venerated heroes among the Yokudan warriors.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_yokudanfullstatuette001.dds",
                        },
                        [8994] = 
                        {
                            ["category"] = "Assistants",
                            ["name"] = "Baron Jangleplume, the Banker",
                            ["id"] = 8994,
                            ["furnitureId"] = 7522,
                            ["description"] = "This Blackfeather Court banker wants your shinies … to keep them safe for you, of course! The chaos of Cyrodiil and Battlegrounds are murder on his plumage, so he won't visit you there.\n\nWhen summoned, his services can be used by you and your groupmates.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/assistant_crowbanker.dds",
                        },
                        [8995] = 
                        {
                            ["category"] = "Assistants",
                            ["name"] = "Peddler of Prizes, the Merchant",
                            ["id"] = 8995,
                            ["furnitureId"] = 7523,
                            ["description"] = "This Blackfeather Court merchant can relieve you of shiny, non-illicit burdens. She avoids Cyrodiil or Battlegrounds, describing them as \"unprofitable\" and \"full of fat-legged giants.\"\n\nWhen summoned, her services can be used by you and your groupmates.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/assistant_crowmerchant.dds",
                        },
                        [6950] = 
