                        [9010] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Black Forge Iron Senche",
                            ["id"] = 9010,
                            ["furnitureId"] = 7526,
                            ["description"] = "Born from the same wretched forges as Dark Anchors, these ebony-alloy senche atronachs manifest in a burst of soul-searing light when called. Though onlookers may feel as if they'll never be warm again, some riders claim they feel nothing while mounted.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_blackforgeironsenche.dds",
                        },
                        [9011] = 
                        {
                            ["category"] = "Canines",
                            ["name"] = "Sunflare Iron Wolf",
                            ["id"] = 9011,
                            ["furnitureId"] = 7525,
                            ["description"] = "A meteoric boom presages the arrival of this summoned atronach wolf, making it a natural for those who prefer to live with flair—and flare! A sunset's ruby radiance lends its hue to this steed's magical glow. Glory in its intense incandescence.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_radironatrowolf.dds",
                        },
                        [11062] = 
