                        },
                        [11064] = 
                        {
                            ["category"] = "General",
                            ["name"] = "Painting: Systres Seaside Manor",
                            ["id"] = 11064,
                            ["furnitureId"] = 8697,
                            ["description"] = "A painting by Vaudrie Barthel that captures the play of light and water at an elegant manor in the Systres Archipelago.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/housing_sys_inc_housingkeyartpainting003.dds",
                        },
                        [11065] = 
                        {
                            ["category"] = "Flying Pets",
                            ["name"] = "Phoenix Moth",
                            ["id"] = 11065,
                            ["furnitureId"] = 8698,
                            ["description"] = "\"Druids say the moths are ash made manifest. They leap from the flames of Mount Firesong and flutter away on the breeze. Nonsense! I've seen a moth ignite and then emerge from the coals like a cocoon.\"—Feather-Brained Teeska",
                            ["hint"] = "Complete the quest \"Guardian of Y'ffelon\" on Galen.",
                            ["icon"] = "/esoui/art/icons/pet_phoenixmoth.dds",
                        },
                        [11067] = 
                        {
                            ["category"] = "Equines",
                            ["name"] = "Harrowstorm Destrier",
                            ["id"] = 11067,
                            ["furnitureId"] = 8699,
                            ["description"] = "The first destrier born from a harrowstorm spurned its original rider and galloped away before any present could capture it. This pattern continued for a time, leading many to wonder where they went. Some say they must find new riders—for good or ill.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_harrowstormcharger.dds",
                        },
                        [6972] = 
                        {
                            ["category"] = "Multi-Rider",
                            ["name"] = "Duo-Dynamo Dwarven Spider",
                            ["id"] = 6972,
                            ["furnitureId"] = 7244,
                            ["description"] = "\"Clearly the Dwarves liked to travel in pairs now and again, so they built this two-seated animunculi for that purpose. My partner and I adore using it on market day!\"—Delyna Ulvel",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["icon"] = "/esoui/art/icons/mount_groupmountspider.dds",
                        },
                        [11069] = 
                        {
                            ["category"] = "Bipedals",
                            ["name"] = "Buoyant Armiger Kagouti",
                            ["id"] = 11069,
                            ["furnitureId"] = 8701,
                            ["description"] = "\"Vile mischief inflicted wounds upon the striped kagouti. 'Lord Vivec must know we have healed this creature who protected his servants. Remembered pain will lead to prevented pain.' And so it befriended the bear and spider.\"—Armiger Tharys's Journal",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerkagouti.dds",
                        },
