                        [11073] = 
                        {
                            ["category"] = "Houseguests",
                            ["name"] = "Stefan Mornard",
                            ["id"] = 11073,
                            ["furnitureId"] = 8818,
                            ["description"] = "With both knightly skills and druidic lore in his repertoire, Sir Stefan Mornard makes for a deadly foe—and a courteous houseguest. After adding Sir Stefan to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/houseguest_sirstefanmornard.dds",
                        },
                        [11074] = 
                        {
                            ["category"] = "Houseguests",
                            ["name"] = "Caska",
                            ["id"] = 11074,
                            ["furnitureId"] = 8817,
                            ["description"] = "Caska the Senche-raht serves as the first mate on The Perfect Pounce, and she loves time off to pursue other interests—perhaps in your house! After adding Caska to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/houseguest_caska.dds",
                        },
                        [11075] = 
                        {
                            ["category"] = "Houseguests",
                            ["name"] = "Mel Adrys",
                            ["id"] = 11075,
                            ["furnitureId"] = 8819,
                            ["description"] = "Vampire hunters such as Mel Adrys travel widely in pursuit of their quarry, and they need places to rest between hunts. Care to host this Dark Elf? After adding Mel to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/houseguest_meladrys.dds",
                        },
                        [11076] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Spellscar Quasigriff",
                            ["id"] = 11076,
                            ["furnitureId"] = 8705,
                            ["description"] = "The unchained potential that emanates from the Spellscar twists and changes everything it touches. Who or what drew a quasigriff to Craglorn is still a mystery, but these esoterically beautiful beasts add something new and transcendent to Tamriel.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_spellscarquasigriff.dds",
                        },
                        [11079] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Firebelly Shalk",
                            ["id"] = 11079,
                            ["furnitureId"] = 8707,
                            ["description"] = "Unlike their more common domesticated cousins, the Firebelly Shalk constantly blazes. Militant Dark Elves sometimes train these Glasscrag Edifice natives to infiltrate the holds of their enemies. Others find them fiery friends on cold Ashlands nights.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_firebellyshalk.dds",
                        },
                        [11082] = 
                        {
                            ["category"] = "Daedric",
                            ["name"] = "Abyssal Tomeshell",
                            ["id"] = 11082,
                            ["furnitureId"] = 8708,
                            ["description"] = "\"Love books, do you? What if they had tentacles and an eye? The gift of flight? Like them as much then? Yes? Oh, delightful! Here, befriend my beloved Philosophicus Aeternum—Philo for short. Expand its knowledge of Nirn.\"—The Archivist of the Lost",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_fangtome.dds",
                        },
                        [11097] = 
                        {
                            ["category"] = "Assistants",
                            ["name"] = "Pyroclast, Infernace Conservator",
                            ["id"] = 11097,
                            ["furnitureId"] = 8997,
                            ["description"] = "Hailing from the pocket realm of Infernace, Pyroclast will holdfast your items (or the items of your groupmates) in the fiery pits of Oblivion. Minor scorching may occur.\n\nAncient bindings prevent them from appearing in Cyrodiil or Battlegrounds.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/assistant_pyroclast.dds",
                        },
                        [11102] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Necrom Armiger Senche",
                            ["id"] = 11102,
                            ["furnitureId"] = 8776,
                            ["description"] = "\"We were all surprised when this senche arrived via envoy. 'A gift from Necrom to an armiger of great repute. Return and aid in the training of more!' And so I ventured to Necrom with a cunning, furry companion.\"—Armiger Tharys's Journal",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_necromarmigersenche.dds",
                        },
