                        [7277] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Gloomspore Wolf Pup",
                            ["id"] = 7277,
                            ["furnitureId"] = 6557,
                            ["description"] = "\"I designed some adorable wolf pups, adding oxblood fungus spores to see if that instills fierce guardianship in them. It worked—they now guard my feet from things like boots and stockings. Consider garbing yourself out of their sight!\"—Mage Naleldil",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_gloomsporewolf.dds",
