                            ["id"] = 1173,
                            ["furnitureId"] = 4388,
                            ["description"] = "\"The Brassilisk is created from interconnected brass squares, its exposed copper wiring allowing for its snakelike movement. Popular as a pet, you'll often see them following the quick footsteps of young scholars.\" —Endilaril, Clockwork City Naturalist",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_162.dds",
                        },
                        [1174] = 
                        {
                            ["category"] = "Canines",
                            ["name"] = "Ebon Dwarven Wolf",
                            ["id"] = 1174,
                            ["furnitureId"] = 4389,
                            ["description"] = "\"There is no evidence that the Dwemer kept dogs, or pets of any other kind, for that matter, but like their neighbors the Nords they did seem to have some affection for the Wolves of northern Tamriel. One sees this in their mounts.\" —Thelwe Ghelein",
                            ["hint"] = "Acquired by digging up its various parts via the Antiquities system.",
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_ebon_wolf.dds",
