                        [11693] = 
                        {
                            ["category"] = "Flying Pets",
                            ["name"] = "Mead-Dancer Honeybee",
                            ["id"] = 11693,
                            ["furnitureId"] = 9525,
                            ["description"] = "\"Bees are simple, really. They respect power. That's why they follow a queen. Just act like you're supposed to be in charge and they'll work for you. Show any weakness, any hesitation? That's when you get stung.\"—Hei Honey-Hands",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_whiterunhoneybee.dds",
                        },
                        [11692] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Winterhold Chestnut Pony",
                            ["id"] = 11692,
                            ["furnitureId"] = 9524,
                            ["description"] = "Every child in Winterhold asks for one of these ponies at some point, and a very lucky few will receive one. Their small stature is perfect for young riders, and even older adults cherish them as cheerful and hardy pets.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_winterholdchestnutpony.dds",
                        },
                        [11691] = 
                        {
                            ["category"] = "Daedric",
                            ["name"] = "Companion Revelry Tomeshell",
                            ["id"] = 11691,
                            ["furnitureId"] = 9523,
                            ["description"] = "\"Look, I know tomeshells need a place to live too, but that's one of the rarest volumes in the archive! Sure, it looks flashy now, but Mora knows what state the book will be in whenever this one decides to move on.\"—Cipher Caldaafin",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_companionstomeshell.dds",
                        },
                        [11657] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Mistral Thunderbug",
                            ["id"] = 11657,
                            ["furnitureId"] = 9494,
                            ["description"] = "Owners of this electrifying little friend must learn to handle the occasional shock from time to time. Thunderbugs are quite expressive, though their main form of communication is through sparks and sharp jolts.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_mistralthunderbug.dds",
                        },
                        [11656] = 
                        {
                            ["category"] = "Camelids",
                            ["name"] = "Pyrodraconic Camel-Lizard",
                            ["id"] = 11656,
                            ["furnitureId"] = 9493,
                            ["description"] = "\"Of course it's not a real Dragon. That's beside the point. Intense hue recoloration, brimstone expectoration, and a fusion of Wood Elf and Telvanni magical techniques? Tell Otheri the contract is fulfilled, and more.\"—Magister Varkenel",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_pyrodraconiccamellizard.dds",
                        },
                        [11652] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Thorn Gecko",
                            ["id"] = 11652,
                            ["furnitureId"] = 9474,
                            ["description"] = "\"He's not the cuddliest pet, sure, but old Spike here is as loyal as they come. I just throw him some grubs every now and then, and he follows me anywhere I go. I like to think he likes the company and not just the snacks.\"—Trapper Marcien",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_thorngecko.dds",
                        },
                        [5600] = 
                        {
                            ["category"] = "Flying Pets",
                            ["name"] = "Hollowjack Netch",
                            ["id"] = 5600,
                            ["furnitureId"] = 5532,
                            ["description"] = "The Witches Festival, which celebrates horror and death, also has a regrettable tradition of wanton vandalism associated with it, especially among Tamriel's callow youth. The so-called \"Hollowjack Netch\" appears to be a victim of this practice.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_205_pumpkinnetch.dds",
                        },
                        [5601] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Snowcap Fledgling Gryphon",
                            ["id"] = 5601,
                            ["furnitureId"] = 5442,
                            ["description"] = "On the highest pinnacles of Eton Nir, where the snow never melts, live the pale Snowcap Gryphons. Perfectly camouflaged for a life in the clouds, for most of the First Era they were considered to be a myth.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_234_snowgryphon.dds",
                        },
                        [5602] = 
