                        [11563] = 
                        {
                            ["category"] = "Houseguests",
                            ["name"] = "Skordo the Knife",
                            ["id"] = 11563,
                            ["furnitureId"] = 9354,
                            ["description"] = "This Orc mercenary usually keeps busy, but now he wants some actual quiet time. Not to reflect, though—his well-used gear needs some attention. After adding Skordo to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/houseguest_skordo.dds",
                        },
                        [11562] = 
                        {
                            ["category"] = "Houseguests",
                            ["name"] = "Mizzik Thunderboots",
                            ["id"] = 11562,
                            ["furnitureId"] = 9353,
                            ["description"] = "With no mysteries for this Khajiit of action to solve, he's at loose ends. Perhaps he can discover some curious doings around your abode? After adding Mizzik to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/houseguest_mizzikthunderboots.dds",
                        },
                        [11561] = 
                        {
                            ["category"] = "Houseguests",
                            ["name"] = "Heiruna",
                            ["id"] = 11561,
                            ["furnitureId"] = 9352,
                            ["description"] = "Oh, the ignominy of being an agent of justice trapped inside a small floating doll! Now Heiruna intends to plot vengeance—in your retreat. After adding Heiruna to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/houseguest_heiruna.dds",
                        },
                        [11537] = 
                        {
                            ["category"] = "Camelids",
                            ["name"] = "Piebald Camel",
                            ["id"] = 11537,
                            ["furnitureId"] = 9350,
                            ["description"] = "\"It appears Sabhir has earned your admiration. This is not the first time his stunning spots have stolen hearts. Shh, don't let him see you looking. He has enough of an ego as it is.\"—Stablehand Ghazaleh",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_piebaldcamel.dds",
                        },
                        [11536] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Shackled Titan",
                            ["id"] = 11536,
                            ["furnitureId"] = 9349,
                            ["description"] = "\"This titan failed the Dark Lord once, and paid the price for it. After he ripped off its wings, Molag Bal bound it to his dark will, making it a useful—if grounded—mount for his more faithful servants.\"—Worm Cultist Valoel",
                            ["hint"] = "|cFFFFFFDaedric Anchor effects appear only when paired with the Molag Bal Illusion polymorph.|r",
                            ["icon"] = "/esoui/art/icons/mount_fallentitan.dds",
                        },
                        [11535] = 
                        {
                            ["category"] = "Equines",
                            ["name"] = "Jubilee Steed",
                            ["id"] = 11535,
                            ["furnitureId"] = 9348,
                            ["description"] = "\"The Imperials do love their regalia, don't they? Even I have to admit it's a rather dashing look, for a horse. Anyone who comes in astride that steed is certain to make an entrance.\"—Abelle Gernand of Kvatch",
                            ["hint"] = "Acquired by completing the \"Jubilee Confetti Conveyor\" achievement.",
                            ["icon"] = "/esoui/art/icons/mount_jubileesteed.dds",
                        },
                        [11534] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Mirrormoor Mudcrab",
                            ["id"] = 11534,
                            ["furnitureId"] = 9347,
                            ["description"] = "\"These mudcrabs developed their shine as both a defensive tactic and mating ritual. By angling their bodies, they can reflect blinding rays at would-be predators or signal their availability to potential mates.\"—Mirrormoor: More Than an Illusion",
                            ["hint"] = "Awarded by completing the \"Prisoner of Fate\" quest.",
                            ["icon"] = "/esoui/art/icons/pet_mirrormoormudcrap.dds",
                        },
                        [11533] = 
                        {
                            ["category"] = "Canines",
                            ["name"] = "Titanborn's Revelry Wolf",
                            ["id"] = 11533,
                            ["furnitureId"] = 9346,
                            ["description"] = "Said to have been tamed by Lyris Titanborn herself, this fierce wolf easily bears its rider across nearly any terrain. While the beast is a frenzied fighter on the battlefield, one word from its rider will have it waiting docilely for the next command.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_companionrevelrywolf.dds",
                        },
                        [11532] = 
                        {
                            ["category"] = "Equines",
                            ["name"] = "Varen's Revelry Courser",
                            ["id"] = 11532,
                            ["furnitureId"] = 9345,
                            ["description"] = "A steed worthy of an emperor, this courser represents the finest traits of Imperial equestrian skill. Steady and strong with an incredibly smooth gait, this mount could help its rider fell countless kingdoms.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_companionrevelryhorse.dds",
                        },
                        [11531] = 
                        {
                            ["category"] = "Ursines",
                            ["name"] = "Sai-Sahan's Revelry Ursine",
                            ["id"] = 11531,
                            ["furnitureId"] = 9344,
                            ["description"] = "\"Ah, this is a beast worthy of a hero! Don't worry, faithful Minana here has seen her share of battles and more than earned the armor she now wears. She will be a staunch companion to you, no matter where HoonDing bids you.\"—Dragonguard Zarina",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_companionrevelrybear.dds",
                        },
                        [11530] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Chorrol Retriever",
                            ["id"] = 11530,
                            ["furnitureId"] = 9343,
                            ["description"] = "These playful golden canines happily accompany their people on journeys near and far, making friends with anyone they meet along the way. The downside to this endearing show of trust is, of course, that they're not the best guard dogs.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_chorralretriever.dds",
                        },
                        [11523] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Celestial Lynx",
                            ["id"] = 11523,
                            ["furnitureId"] = 9341,
                            ["description"] = "Swift as a stream and silent as a shadow, this creature appears in many folktales across Tamriel. In some, the lynx stalks its quarry across the night sky. In others it's an agile companion, perfect for worthy hunters prowling the darkest nights.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_celestiallynx.dds",
                        },
                        [11522] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Atmoran Snow Ursauk",
                            ["id"] = 11522,
                            ["furnitureId"] = 9333,
                            ["description"] = "Though fearsome in appearance, these ursauks make staunch companions when properly socialized. Their thick fur and hardy constitutions allow them to thrive even in the harshest environments, especially those in the northern reaches of Tamriel.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_atmoransnowursauk.dds",
                        },
                        [5619] = 
                        {
                            ["category"] = "Daedric",
                            ["name"] = "Daemon Chicken",
                            ["id"] = 5619,
                            ["furnitureId"] = 5475,
                            ["description"] = "Is this just a dark fowl, mere poultry of sinister visage—or does it hail from realms beyond Nirn, mayhap from the Deadlands of Mehrunes Dagon or the Ashpit of Malacath? Dare you ask yourself the dread question: Which came first?",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_203_blackchicken.dds",
                        },
                        [5620] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Riverwood White Hen",
                            ["id"] = 5620,
                            ["furnitureId"] = 5476,
                            ["description"] = "A hardy domestic chicken found all along Skyrim's White River, said to have been originally bred in the old town of Riverwood. Owners grow extremely attached to them, and become outraged if they're harmed.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_215_roosterwhite.dds",
                        },
                        [11520] = 
                        {
                            ["category"] = "Serpentes",
                            ["name"] = "Altered Ornaug",
                            ["id"] = 11520,
                            ["furnitureId"] = 9331,
                            ["description"] = "This beast is the result of a collaboration between Shad Astula students and Mages Guild apprentices. Rumor is it may be slightly psychic, responding to its rider's commands almost before they're uttered aloud. The color is a nice bonus, too.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_alterationornaug.dds",
                        },
                        [11519] = 
                        {
                            ["category"] = "Undaunted Trophies",
                            ["name"] = "Trophy: Ansuul the Tormentor",
                            ["id"] = 11519,
                            ["furnitureId"] = 9329,
                            ["description"] = "Trophy taken from Ansuul the Tormentor in honor of an Undaunted victory in Sanity's Edge.",
                            ["hint"] = "Awarded for completing Sanity's Edge.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyvaerminagloamknight001.dds",
                        },
                        [11518] = 
                        {
                            ["category"] = "Undaunted Busts",
                            ["name"] = "Bust: Ansuul the Tormentor",
                            ["id"] = 11518,
                            ["furnitureId"] = 9328,
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Sanity's Edge.",
                            ["hint"] = "Awarded for completing Veteran Sanity's Edge.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialvaerminagloamknight001.dds",
                        },
                        [11515] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Prismatic Senche Cub",
                            ["id"] = 11515,
                            ["furnitureId"] = 9270,
                            ["description"] = "\"This cub is special, yes. Beautiful and quite friendly. Not the softest companion, but others have said the same about me.\"—Scholar Zansora",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_prismaticsenchecub.dds",
                        },
                        [11514] = 
                        {
                            ["category"] = "Flying Pets",
                            ["name"] = "Conjured Dragon Imp",
                            ["id"] = 11514,
                            ["furnitureId"] = 9269,
                            ["description"] = "This impressive vision is the work of a very dedicated illusion imp. The shimmering form sparks the adoration of all who see it, making for easy handouts and safe havens for this tiny so-called Dragon.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_conjureddragonimp.dds",
                        },
                        [11513] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Destruction Dale Fawn",
                            ["id"] = 11513,
                            ["furnitureId"] = 9268,
                            ["description"] = "Though alarming at first glance, this fawn is perfectly content with its strangely blazing body. Those who can tame this extreme example of mystical adaptation will find its back an excellent medium for cooking over an open flame.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_tinderflarevalefawn.dds",
                        },
                        [11508] = 
                        {
                            ["category"] = "Camelids",
                            ["name"] = "Sword-Singer's Tufted Camel",
                            ["id"] = 11508,
                            ["furnitureId"] = 9266,
                            ["description"] = "\"HoonDing knows they don't look fast. But that's actually a good thing. No one will expect you to cover as much ground as you do. And there is truly nothing more terrifying than a camel charging you at full speed.\"—Bilami the Caravaneer",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_swordsingerstuftedcamel.dds",
                        },
                        [11507] = 
                        {
                            ["category"] = "Flying Pets",
                            ["name"] = "Emerald Oak Nixad",
                            ["id"] = 11507,
                            ["furnitureId"] = 9265,
                            ["description"] = "\"Emerald Oak Nixads are known for their mischief. Their coloration allows them to hide in forests, waiting for unsuspecting travelers to pass by. Upon leaving, travelers will find their rations much lighter, especially sweets.\"—Gold Coast Field Guide",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_emeraldoaknixad.dds",
                        },
                        [11506] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Sugarsnow Monkey",
                            ["id"] = 11506,
                            ["furnitureId"] = 9264,
                            ["description"] = "\"Watch your moon sugar around these ones. They have keen eyes and clever hands. This one has lost her lunch to Zuzdu more times than she can count. Still, they can be quite sweet when they want to be. Probably from all the stolen sugar.\"—Tahara",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_moonsugarmonkey.dds",
                        },
                        [11505] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Ruby Haj Mota",
                            ["id"] = 11505,
                            ["furnitureId"] = 9263,
                            ["description"] = "The eye-catching hue of this haj mota may be beautiful, but it belies a fiery demeanor. Haj motas are known for their harsh temperaments, but this one is not to be trifled with. Thankfully, it's too small to do more than snap at ankles.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_lus_begottenhajmota.dds",
                        },
                        [11472] = 
                        {
                            ["category"] = "General",
                            ["name"] = "Statuette: Mora, Lord of Secrets",
                            ["id"] = 11472,
                            ["furnitureId"] = 9232,
                            ["description"] = "All statues of the Inevitable Knower are, after a fashion, access points from Apocrypha to Nirn. Given that, go carefully as you invite Hermaeus Mora into your home.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_hermaeusmorastatuette001.dds",
                        },
                        [11457] = 
                        {
                            ["category"] = "Ursines",
                            ["name"] = "Brindle Bear",
                            ["id"] = 11457,
                            ["furnitureId"] = 9220,
                            ["description"] = "\"I've only seen a wild brindle bear once, and I don't wish to repeat the experience. The creature found me in the woods, bagging up a deer. It growled. I froze. But then it walked right by me. It must have already eaten.\"—Scarius Barbatus of Kvatch",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_brindlebear.dds",
                        },
                        [11454] = 
                        {
                            ["category"] = "Cervines",
                            ["name"] = "Galerion's Indrik",
                            ["id"] = 11454,
                            ["furnitureId"] = 9190,
                            ["description"] = "Gilded from head to hoof, this indrik practically glows with the light of inspiration. It may have been a fabled companion of Vanus Galerion. Whether or not the legends are true, its rider will see a world full of shimmering ideas and possibilities.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_lightgiverindrik.dds",
                        },
                        [11441] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Solstheim Shiver Wolf",
                            ["id"] = 11441,
                            ["furnitureId"] = 9153,
                            ["description"] = "Many have met their ends at the jaws of a fully grown Solstheim wolf. This trained version, however, still has snowflakes in its fur and frolics whenever it comes across a fresh snow drift. It even gives freezing cold kisses when called.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_solstheimtundrawolf.dds",
                        },
                        [11438] = 
                        {
                            ["category"] = "Serpentes",
                            ["name"] = "Buraniim Isle Ornaug",
                            ["id"] = 11438,
                            ["furnitureId"] = 9149,
                            ["description"] = "The shallows of Buraniim Isle are rife with a unique subspecies of ornaug. Vibrant and playful, these ornaugs have been known to splash in the surf to attract the curiosity of would-be prey. When the unsuspecting meal draws too close, they strike.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_buraniim-ornaug.dds",
                        },
                        [11437] = 
                        {
                            ["category"] = "Houseguests",
                            ["name"] = "Scruut",
                            ["id"] = 11437,
                            ["furnitureId"] = 9133,
                            ["description"] = "Divergences in fate's threads draw Scruut's attention. Yet, this mighty Watchling seeks your company until the Great Eye summons her. Coincidence? After adding Scruut to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/houseguest_scruut.dds",
