                        [11425] = 
                        {
                            ["category"] = "Bipedals",
                            ["name"] = "Order of the Lamp Vvardvark",
                            ["id"] = 11425,
                            ["furnitureId"] = 9116,
                            ["description"] = "Though not the most fearsome mounts, these recent additions to the Lamp Knight stable are treasured for their loyalty, surefootedness, and tracking skills. Some mages claim they can smell magicka, making them invaluable to the Order of the Lamp.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_orderofthelampvvardvark.dds",
                        },
                        [9743] = 
                        {
                            ["category"] = "Assistants",
                            ["name"] = "Factotum Property Steward",
                            ["id"] = 9743,
                            ["furnitureId"] = 7947,
                            ["description"] = "This factotum exists to serve as your personal banker—except in Cyrodiil or Battlegrounds, where it shuts down and vanishes to hyperogonal points unknown.\n\nAfter it's summoned, you and your groupmates can use its services.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/assistant_factotumbanker.dds",
                        },
                        [9744] = 
                        {
                            ["category"] = "Assistants",
                            ["name"] = "Factotum Commerce Delegate",
                            ["id"] = 9744,
                            ["furnitureId"] = 7948,
                            ["description"] = "Need to sell a few things? Do so with this shiny factotum—except in Cyrodiil or Battlegrounds, which initiate its retreat protocols.\n\nAfter it's summoned, you and your groupmates can use its services.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/assistant_factotummerchant.dds",
                        },
                        [9745] = 
                        {
                            ["category"] = "Assistants",
                            ["name"] = "Ghrasharog, Armory Assistant",
                            ["id"] = 9745,
                            ["furnitureId"] = 7949,
                            ["description"] = "You and your groupmates can prepare for combat by summoning Ghrasharog to change and save builds outside of your home. He avoids Cyrodiil or Battlegrounds, which he swears made him complacent after winning victory upon victory.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/assistant_ghrashorogmasteratarms.dds",
                        },
                        [11424] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Order of the Lamp Lion",
                            ["id"] = 11424,
                            ["furnitureId"] = 9115,
                            ["description"] = "\"Magicka depleted. Enemies on all sides. The cornered mages despaired. Until they heard a growl erupt into a roar as a Lamp Knight and his leonine steed smashed through the enemy ranks.\"—Tale of the Palatinus, translated",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_orderofthelamplion.dds",
                        },
                        [11403] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Welkyndstone Ruins Pup",
                            ["id"] = 11403,
                            ["furnitureId"] = 9034,
                            ["description"] = "\"The Wild Elves did something right when they tamed these adorable beasties! Look at those eyes, and that tail! Plus with that handsome armor, they'll be well protected on the road.\" —Apprentice Odrethin",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_wenayawend-wolf-pup.dds",
                        },
                        [5652] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Scruffy Skyrim Paint Pony",
                            ["id"] = 5652,
                            ["furnitureId"] = 5852,
                            ["description"] = "Hardy and good-natured, the faithful Skyrim Paint Pony wants to be near its master regardless of the weather, leaning into the wind even in a tundra blizzard.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_213_paintedpony.dds",
                        },
                        [11402] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Deepsnow Prairie Dog",
                            ["id"] = 11402,
                            ["furnitureId"] = 9033,
                            ["description"] = "\"Cute little critters, aren't they? The white pelt helps them blend into the mountains of Skyrim. That's good, because they're just about the tastiest thing the winter has to offer. Except for that one. He's off limits.\"—Narrald Snow-Bourne",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_deepsnowprairiedog.dds",
                        },
                        [11391] = 
                        {
                            ["category"] = "Houseguests",
                            ["name"] = "Azandar",
                            ["id"] = 11391,
                            ["furnitureId"] = 9174,
                            ["description"] = "Azandar al-Cybiades is a consummate researcher and peerless arcanist. Just ask him! After adding Azandar to your home, you can set him on a path. You and your guests can also talk to him. Trust us, he's got plenty to say.",
                            ["hint"] = "Obtained by completing quest \"Tempting Fates.\"",
                            ["icon"] = "/esoui/art/icons/houseguest_azandar_2.dds",
                        },
                        [11390] = 
                        {
                            ["category"] = "Houseguests",
                            ["name"] = "Sharp-as-Night",
                            ["id"] = 11390,
                            ["furnitureId"] = 9175,
                            ["description"] = "Solitary mercenary Sharp-as-Night isn't used to company, but if you invite him into your home, this warden will leave his icy demeanor at the door. Mostly. Talk to him to hear his unfiltered thoughts, or set him on a path to let him wander your estate.",
                            ["hint"] = "Obtained by completing quest \"Light the Way to Freedom\".",
                            ["icon"] = "/esoui/art/icons/houseguest_sharp.dds",
                        },
                        [5656] = 
                        {
                            ["category"] = "Flying Pets",
                            ["name"] = "Swamp Jelly",
                            ["id"] = 5656,
                            ["furnitureId"] = 5541,
                            ["description"] = "Though obviously related to the netches of northeast Tamriel, the swamp jellies of southern Black Marsh also have a disquieting resemblance to aquatic jellyfish. Natural philosophers have no adequate explanation for this.",
                            ["hint"] = "Acquired by finding its seven Runebox Fragments in Cyrodilic Collections Daily Contract Recompense containers and combining them.",
                            ["icon"] = "/esoui/art/icons/pet_206_swampjelly.dds",
                        },
                        [5657] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Kaleidotropic Dragon Frog",
                            ["id"] = 5657,
                            ["furnitureId"] = 5547,
                            ["description"] = "This little critter's bright, beautiful colors are actually a warning to predators that it's a potent mouthful of poison. Fortunately for Tamriel's humanoid mortals, its venom affects them as no more than a mild hallucinogen.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_211_kaleidascope.dds",
                        },
                        [5658] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Butterscotch Dragon Frog",
                            ["id"] = 5658,
                            ["furnitureId"] = 5548,
                            ["description"] = "\"The Butterscotch Dragon Frog presumably got its name from the Argonian practice of naming creatures after flavors, whether those things taste like that or not. This one has no intention of finding out whether it does.\" —M'aiq the Liar",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_207_butterscotch.dds",
                        },
                        [5659] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Flame Skin Salamander",
                            ["id"] = 5659,
                            ["furnitureId"] = 5552,
                            ["description"] = "All the large Salamanders of southern Tamriel have elemental powers, but some specialize in particular forces; the Flame Skin breed, for example, almost ripples with fire.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_208_orangesalamander.dds",
                        },
                        [5660] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Toxin Skin Salamander",
                            ["id"] = 5660,
                            ["furnitureId"] = 5553,
                            ["description"] = "The large, lumbering Salamanders of southern Tamriel are known for defending themselves with various elemental bursts—all but one, the Toxin Skin variety, which relies on venom instead. Not even the Sapiarchs of the Crystal Tower can account for it.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_210_greensalamander.dds",
                        },
                        [5661] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Shock Skin Salamander",
                            ["id"] = 5661,
                            ["furnitureId"] = 5554,
                            ["description"] = "The lumbering great Salamanders of southern Tamriel all defend themselves with bursts of elemental power, but the Shock Skin variety specializes in electrical discharges. Fortunately, they can be trained not to zap their masters!",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_209_bluesalamander.dds",
                        },
                        [5662] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Prong-Eared Odd-Eyed Cat",
                            ["id"] = 5662,
                            ["furnitureId"] = 5557,
                            ["description"] = "\"Cats with odd-colored eyes see into the depths of those around them. Those with white fur? They see into time itself.\" —Zamarak",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_prongearoddeyed-cat.dds",
                        },
                        [11380] = 
                        {
                            ["category"] = "Flying Pets",
                            ["name"] = "Hearthhome Moth",
                            ["id"] = 11380,
                            ["furnitureId"] = 9021,
                            ["description"] = "These ponderous moths flap slowly between pools of moonlight, attracted by the glow. During the day, they either rest on shady tree trunks or follow behind those who make them feel safe. Their delicate wings are famously soft to the touch.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_hearthhomemoth.dds",
                        },
                        [11379] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Prodigious Crimson Mudcrab",
                            ["id"] = 11379,
                            ["furnitureId"] = 9020,
                            ["description"] = "\"How many times have I told you to keep your fingers away from the claws? Now look at you, knuckles bruised and nothing learned. The crab did nothing wrong. Maybe it's time this one found a more appropriate home.\"—Overheard on the Necrom docks",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_prodigiouscrimsonmudcrab.dds",
                        },
                        [11326] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Black Fredas Senche-Lizard",
                            ["id"] = 11326,
                            ["furnitureId"] = 8999,
                            ["description"] = "Some find the color unnerving, but many riders enjoy the onyx shade and welcome the superstitious tales that follow this mount. Just know that countless legends and tales of woe begin when a Black Fredas beast crosses one's path.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_blackfredassenchelizard.dds",
                        },
                        [11240] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Sagacious Psijic Senche-Raht",
                            ["id"] = 11240,
                            ["furnitureId"] = 8995,
                            ["description"] = "Aloof and strangely mournful, there's no question Pirzbi wields powerful magic. Some say their innate ability and keen intellect have become an obstacle for those who wish to partner with them. Perhaps you will find success where they did not.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_sagaciouspsijicsencheraht.dds",
                        },
                        [11239] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Silent Moons Sheep",
                            ["id"] = 11239,
                            ["furnitureId"] = 8994,
                            ["description"] = "Docile and hardy, these sheep were first tamed near Whiterun. Their thick wool is woven into cloaks and blankets, protecting the wearer during harsh winters. Nord children sometimes bed down among the flock, enjoying the sheep's warmth.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_silentmoonssheep.dds",
                        },
                        [11238] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Shezarr's Chicken",
                            ["id"] = 11238,
                            ["furnitureId"] = 8993,
                            ["description"] = "Some claim this breed of bird from Cyrodiil's heartland has a deeper connection to Shezarr than the name. This is likely due to their escape artist reputation, which finds them \"being misplaced\" quite regularly.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_shezarrchicken.dds",
                        },
                        [11237] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Star-Orphan Fawn",
                            ["id"] = 11237,
                            ["furnitureId"] = 8992,
                            ["description"] = "Aethereal light pours off this unearthly fawn. Some say it's a blessing from the Divines, while others think it's a Daedric trick. Still, it's a rare thing to be trusted by such an elusive creature, placing its companions in auspicious company.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_star-orphan-fawn.dds",
                        },
                        [11233] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Ginger Pocket Mammoth",
                            ["id"] = 11233,
                            ["furnitureId"] = 8989,
                            ["description"] = "Much like the pocket mammoths first domesticated near Bonerock Cavern, these creatures are docile and affectionate, plus make excellent livestock. This sub-species is particularly prized among breeders for its distinctive fur color.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_gingerpocketmammoth.dds",
                        },
                        [11232] = 
                        {
                            ["category"] = "Bipedals",
                            ["name"] = "Lavender Guar",
                            ["id"] = 11232,
                            ["furnitureId"] = 8968,
                            ["description"] = "Guar have long been at home in the Black Marsh, making them steady companions to the Argonians. It is not uncommon for Lavender Guar to bond deeply with their riders, standing watch while they sleep and affectionately nuzzling them.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_lavenderguar2.dds",
