                        },
                        [11210] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Clockwork Nix-Hound",
                            ["id"] = 11210,
                            ["furnitureId"] = 8951,
                            ["description"] = "A fabricant from the hidden laboratories of Sotha Sil, the clockwork nix-hound is a small but lifelike imitation. It even \"hunts\" and consumes tiny scraps of metal in its vicinity. Watch out for your coinpurse!",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_clockworknixhound.dds",
                        },
                        [11209] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Ebony Dwarven Scarab",
                            ["id"] = 11209,
                            ["furnitureId"] = 8950,
                            ["description"] = "\"Some of father's creations can be so frightening what with the way they hiss and stutter, but not this small scarab, no. After all, its bright glow does wonders to keep the monsters beneath my bed at bay.\"—Fabricator Anzalf's Daughter",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_ebonyscarab.dds",
                        },
                        [11204] = 
                        {
                            ["category"] = "Cervines",
                            ["name"] = "Hollowjack Indrik",
                            ["id"] = 11204,
                            ["furnitureId"] = 8937,
                            ["description"] = "\"Twisted twigs, a scent of death, a dance amid the briars. A dash of howls and drip of gore starts sinister fires. Stir round with haunted bone, then call me with your screams. If I approve, a mount you gain to torment your foes' dreams.\"—Lord Hollowjack",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_hollowjackindrik.dds",
                        },
                        [11203] = 
                        {
                            ["category"] = "Bipedals",
                            ["name"] = "Ashmourning Vvardvark",
                            ["id"] = 11203,
                            ["furnitureId"] = 8936,
                            ["description"] = "Originally seen as a mistake by its creator, vvardvarks grew in popularity, compelling Telvanni magisters to expand its development. This dark-hued mount is perfectly suited to carry riders in funerary processions honoring revered ancient ancestors.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_ashmournvvardvark.dds",
                        },
                        [11202] = 
                        {
                            ["category"] = "Cervines",
                            ["name"] = "Star-Orphan Elk",
                            ["id"] = 11202,
                            ["furnitureId"] = 8934,
                            ["description"] = "\"After weeks of searching, I finally caught a glimpse of that illustrious beast on the horizon. I thought it was a vision from Meridia, but then it approached on the icy tundra and I felt the warmth of its breath on my hand.\" —Journal of Mage Abzrolg",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_starorphanelk.dds",
                        },
                        [9775] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Aurielic Quasigriff",
                            ["id"] = 9775,
                            ["furnitureId"] = 7951,
                            ["description"] = "Taken from the nest almost as soon as it breaks through its shell, this quasigriff is pampered and preened as befits a creature sacred to Auriel. Its golden feathers are used as fletching by archers in Balfiera.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_aurielicquasigriff.dds",
                        },
                        [11201] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Blessed Highmane Lion",
                            ["id"] = 11201,
                            ["furnitureId"] = 8933,
                            ["description"] = "\"And thus did Alkosh bestow a companion of pure light upon his champion. From atop the beast, the champion rode a noble path. And wherever the lion's paws fell, light and justice soon followed thereafter.\" —Path of the Highmane, translated",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_alkoshs-blessing-lion.dds",
                        },
                        [11200] = 
                        {
                            ["category"] = "Houseguests",
                            ["name"] = "Filbert Cienne",
                            ["id"] = 11200,
                            ["furnitureId"] = 8932,
                            ["description"] = "Ready to learn more about Peryite, the Prince of Pestilence? Then Filbert's ready to visit and share his knowledge. After adding Filbert to your home, you can set him on a path, plus you and your visitors can speak with him.",
