                        [9829] = 
                        {
                            ["category"] = "Toys",
                            ["name"] = "Stitchedwell Stick Guar",
                            ["id"] = 9829,
                            ["furnitureId"] = 8061,
                            ["description"] = "Soul Shriven knights ride only the most finely stitched steeds. As one old knight proclaimed, \"Don't mind the bit of fray at the bottom there. Or the pesky splinters sticking out of the handle. This guar is a jolly smooth ride!\"",
                            ["hint"] = "|cff0000This mount doesn't increase your movement speed. Riding Lessons don't affect its appearance. This mount cannot path when placed as a furnishing.|r",
                            ["icon"] = "/esoui/art/icons/mount_stitchedwellstitchguar.dds",
                        },
                        [11878] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Strid River Crab",
                            ["id"] = 11878,
                            ["furnitureId"] = 9561,
                            ["description"] = "Often found crawling up the banks of the Strid River, these crabs have recently made their way upstream into West Weald. While they taste delicious, many collectors prefer to keep them as pets thanks to their dazzling color.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_stridrivercrab.dds",
                        },
                        [11879] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Cream and Coffee Sheep",
                            ["id"] = 11879,
                            ["furnitureId"] = 9562,
                            ["description"] = "Rarer than their alabaster cousins in High Rock, these spotted sheep are beloved for their gentle demeanors and extra soft wool. Many inexperienced farmers can't resist their sweet faces, and these sheep have been known to grow fat on extra treats.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_coffeespottedsheep.dds",
                        },
                        [11880] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Anchorborn Welwa",
                            ["id"] = 11880,
                            ["furnitureId"] = 9563,
                            ["description"] = "Born in the blasted wastes of Coldharbour, Molag Bal's ferocious welwa pursue their prey with terrifying tenacity. It is said that only the chains of the Dark Anchors themselves can hold the beasts back once they've scented their quarry.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_coldharbourwelwa.dds",
                        },
                        [11881] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Meownimarco",
                            ["id"] = 11881,
                            ["furnitureId"] = 9564,
                            ["description"] = "This feline fixes you with a gaze that seems to say, \"Your attempts to pet me are presumptuous! Do you think mice can stop the most powerful catromancer Tamriel has ever known? This form is my first step toward immortality! Witness my true kitty power!\"",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_meownimarco.dds",
                        },
                        [7786] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Cursebound Senche-Raht",
                            ["id"] = 7786,
                            ["furnitureId"] = 6729,
                            ["description"] = "Once known as the toughest Baandari thief in the Stitches, Abahayda ran afoul of a terrible curse in the Ashen Scar. She seeks a companion who will help restore her former life and vigor. Is that you?",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_curseboundraht.dds",
                        },
                        [10709] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Legion Zero Sabre Cat",
                            ["id"] = 10709,
                            ["furnitureId"] = 8601,
                            ["description"] = "After forcing sabre cats to drink the Blood of Coldharbour, Legion Zero soldiers mounted up and secured the Imperial City Nobles District for Mannimarco. Many of these soldiers died, leaving their steeds without riders. Perfect—for you, anyway.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_legionzerosabrecat.dds",
                        },
                        [7788] = 
                        {
                            ["category"] = "Equines",
                            ["name"] = "Valiant Sovngarde Charger",
                            ["id"] = 7788,
                            ["furnitureId"] = 6730,
                            ["description"] = "\"It's said that when a worthy Nord seeks a glorious end, Sovngarde will send them a fleet steed to spirit them to their final battle, but pay no mind to skalds who sing of a horse of many legs.\"—Clever Woman Moritra",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/horse_goldensteed.dds",
                        },
                        [7789] = 
                        {
                            ["category"] = "Canines",
                            ["name"] = "Sovngarde Clawthane Wolf",
                            ["id"] = 7789,
                            ["furnitureId"] = 6731,
                            ["description"] = "\"The clawthanes of Sovngarde often stand watch over the Whalebone Bridge, but some choose to join forces with a courageous soul in Skyrim or beyond. Noble wolves, these are, and clever.\"—Clever Woman Moritra",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_sovngardeclawthanewolf.dds",
                        },
                        [7790] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Sovngarde Valorfang Sabre Cat",
                            ["id"] = 7790,
                            ["furnitureId"] = 6732,
                            ["description"] = "\"Lithe sabre cats are prized among Sovngarde's heroes, particularly those called valorfangs, who died while defending their riders. They stand ready at the Hall of Valor, waiting to convey a hero to a warrior in need of aid.\"—Clever Woman Moritra",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_goldensteedsabercat.dds",
                        },
                        [11887] = 
                        {
                            ["category"] = "Multi-Rider",
                            ["name"] = "Nightmare Pillion Courser",
                            ["id"] = 11887,
                            ["furnitureId"] = 9569,
                            ["description"] = "\"Beware lone roads and moonless nights. Beware the haunted hooves. Beware the burning-coal eyes and the fiery trail that follows each dogged step. Most of all, beware of the path of the steed's terrible riders.\"—Folk Legends of Tamriel",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["icon"] = "/esoui/art/icons/mount_nightmarepillioncharger.dds",
                        },
                        [10646] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Obsidian Dwarven Sphere",
                            ["id"] = 10646,
                            ["furnitureId"] = 8574,
                            ["description"] = "Zuugarz of Orsinium says she first discovered these obsidian-worked animunculi, a claim backed up by the loyal construct that follows her around. She's since learned her scholarly companion \"gifted\" it to her, but that's not something she's eager to share.",
                            ["hint"] = "Acquired by completing the achievement \"Keeper of the Bastion.\"",
                            ["icon"] = "/esoui/art/icons/pet_obsidiandwarvensphere.dds",
                        },
                        [10645] = 
                        {
                            ["category"] = "Canines",
                            ["name"] = "Duskember Fox",
                            ["id"] = 10645,
                            ["furnitureId"] = 8573,
                            ["description"] = "A rare sight, these colorful foxes keep to the shadows in the wild. When trained to the saddle, they proudly display their glossy coats and fine saddlery. Their favorite food is snow berries, and they will do almost anything for their daily treat.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_duskemberfox.dds",
                        },
                        [10644] = 
                        {
                            ["category"] = "Flying Pets",
                            ["name"] = "Xylo Pollen Bat",
                            ["id"] = 10644,
                            ["furnitureId"] = 8572,
                            ["description"] = "These brown-furred bats pollinate flowers along the Xylo River. Without them, nature's web in the Valenwood would be deeply disrupted. Plus they look adorable when they sneeze.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_pollenbat.dds",
                        },
                        [7795] = 
                        {
                            ["category"] = "Ursines",
                            ["name"] = "Sovngarde Stoutheart Bear",
                            ["id"] = 7795,
                            ["furnitureId"] = 6734,
                            ["description"] = "\"During times of great need, Sovngarde releases some of its heroes back into the world, and legendary beasts to serve them. The stoutheart bear is one such creature. A fearless companion to carry true warriors to battle.\"—Clever Woman Moritra",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_sovngardebear.dds",
                        },
                        [7796] = 
                        {
                            ["category"] = "Bipedals",
                            ["name"] = "Valorous Sovngarde Guar Strider",
                            ["id"] = 7796,
                            ["furnitureId"] = 6735,
                            ["description"] = "\"Guar who fall in battle earn a place in Sovngarde. Some later walk among us, serving as faithful and courageous mounts to those who dedicate themselves to brave acts. They leap quickly into action when called.\"—Clever Woman Moritra",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_goldensteedguar.dds",
                        },
                        [7797] = 
                        {
                            ["category"] = "Camelids",
                            ["name"] = "Resplendent Sovngarde Camel",
                            ["id"] = 7797,
                            ["furnitureId"] = 6736,
                            ["description"] = "\"Camels do indeed thrive within Sovngarde. When called to join battle in Tamriel, these resplendent creatures eagerly race forward to meet their valorous riders. Do not believe the claims that they spit mead, though.\"—Clever Woman Moritra",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/camelmount_goldensteed.dds",
                        },
                        [10633] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Inkfur Ursauk",
                            ["id"] = 10633,
                            ["furnitureId"] = 8571,
                            ["description"] = "\"Tales say Grahtwood's ancient oaks called these black-furred ursauks from the deep woods. But why? Every reason this one hears is different! Guards for a sapling grove. Help with a werewolf problem. Or maybe for bear hugs.\"—Zhiraz, Traveling Farmhand",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_inkheartmonstrousbear.dds",
                        },
                        [10632] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Grahtwood Fisher",
                            ["id"] = 10632,
                            ["furnitureId"] = 8570,
                            ["description"] = "\"Each morning during my travels around Grahtwood, one of the local fishers clung to the trunk of a nearby tree. I think it wanted some of my breakfast, so on the third day, I shared. Now it follows me everywhere.\"—Nurome",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_grahtwoodfisher.dds",
                        },
                        [10605] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Brindle Bear Cub",
                            ["id"] = 10605,
                            ["furnitureId"] = 8553,
                            ["description"] = "These adventurous cubs love playing in waterfalls, often using crevices behind them as lairs during the winter. The smell of butter draws them like nothing else. As a result, some claim a dairy farmer first tamed one of these cubs.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_kvatchbrindlebearcub.dds",
                        },
                        [10604] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Duskfall Ancestor Lizard",
                            ["id"] = 10604,
                            ["furnitureId"] = 8552,
                            ["description"] = "\"To fear change wastes time one could spend engaging with the moment. These dark creatures are gifts from our past to both voh-vastei and those who need to be led into the present.\"—Nisswo Uaxal",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_duskfallancestorlizard.dds",
                        },
                        [10600] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Duskfall Welwa",
                            ["id"] = 10600,
                            ["furnitureId"] = 8550,
                            ["description"] = "Using knowledge gained from the forbidden book Occaecium Beluaria, followers of Hermaeus Mora transformed a welwa into a multi-hued, darkly shimmering steed. He allows his most experienced agents in Tamriel to use them for overland tasks.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_oilslickwelwa.dds",
                        },
                        [10599] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Umbral Striped Senche-Raht",
                            ["id"] = 10599,
                            ["furnitureId"] = 8549,
                            ["description"] = "When this beautiful beast lost their rider while traversing a labyrinth, this banded Senche-raht left to seek mystical help to get back inside. Since their efforts often lead them into peril, Nushaben hopes to find a partner for the long journeys ahead.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_umbralstripesencheraht.dds",
                        },
                        [10587] = 
                        {
                            ["category"] = "General",
                            ["name"] = "Sacred Hourglass of Alkosh",
                            ["id"] = 10587,
                            ["furnitureId"] = 8679,
                            ["description"] = "You may place the hourglass within your home. Focusing on its falling sands causes them to blur, and local perception of time to shift. Until the hourglass is disturbed, time seems to stand still. Enjoy everything from eternal sunrises to endless nights.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_antsealkoshhourglass001_fx.dds",
                        },
                        [10586] = 
                        {
                            ["category"] = "Multi-Rider",
                            ["name"] = "Mara's Pledge Mare",
                            ["id"] = 10586,
                            ["furnitureId"] = 8547,
                            ["description"] = "In some towns, pledging oaths before Mother Mara is accompanied by a lavish gift. Legends describe a steed exchanged at Bravil, white as fresh snow and adorned with spring's first flowers. And thus a tradition was born that has survived until today.",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["icon"] = "/esoui/art/icons/mount_mothermaramarehorse.dds",
                        },
                        [10582] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Biscuit Bear-Dog",
                            ["id"] = 10582,
                            ["furnitureId"] = 8546,
                            ["description"] = "Hunters often rely on the services of a loyal dog to protect them as they retrieve their kills. This breed not only ensures that their hunter remains well-guarded, but also provides quiet companionship.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_chorralbirddog.dds",
                        },
