                        },
                        [10290] = 
                        {
                            ["category"] = "Canines",
                            ["name"] = "New Moon Fox",
                            ["id"] = 10290,
                            ["furnitureId"] = 8304,
                            ["description"] = "\"Do not underestimate the foxes trained by the Cult of the New Moon. Their glowing crimson eyes should be enough to warn you away. If you are foolish enough to attempt to steal an adult, say farewell to Nirn.\"—Jonnet of the Sunwalkers",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_newmoonfox.dds",
                        },
                        [10277] = 
                        {
                            ["category"] = "Flying Pets",
                            ["name"] = "Lemondot Netch",
                            ["id"] = 10277,
                            ["furnitureId"] = 8300,
                            ["description"] = "\"Do colors seem louder? Does music taste different? Does Tirdas have a personality? You're probably experiencing the synesthesic venom of the rare lemondot netch. Relax. It's harmless. A little new perspective never killed anybody.\"—Alinon the Alchemist",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_lemondotnetch.dds",
                        },
                        [10244] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Speckled Welwa",
                            ["id"] = 10244,
                            ["furnitureId"] = 8286,
                            ["description"] = "This savage welwa so interested members of the College of Sapiarchs that they brought several to Sil-Var-Woad for study. To help endear them to the public, an enterprising conservator trained them to saddle and \"lent\" them out into the wild.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_speckledwelwa.dds",
                        },
                        [10243] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Anchorborn Pony",
                            ["id"] = 10243,
                            ["furnitureId"] = 8285,
                            ["description"] = "\"Now, I says to my friend, look at all this dark anchor debris. No one's using it. No one owns it. And I look at his pony, this sickly little thing, and I say, why not make ourselves something nice?\"—\"Innovator\" Delan",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_planemeldpony.dds",
                        },
                        [10242] = 
                        {
                            ["category"] = "Canines",
                            ["name"] = "Stormsurge Howler",
                            ["id"] = 10242,
                            ["furnitureId"] = 8280,
                            ["description"] = "Covered in coral and barnacles, this unusual sea creature moves like rushing water, creating a smooth traveling experience for its riders. Some speculate that Kyne crafted them from a sea storm and sent them to land to find those who revere her.",
                            ["hint"] = "Awarded by earning the \"Swashbuckler Supreme\" achievement.",
                            ["icon"] = "/esoui/art/icons/mount_stormsurgehowler.dds",
                        },
                        [10240] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Rustpelt Sabre Cat",
                            ["id"] = 10240,
                            ["furnitureId"] = 8277,
                            ["description"] = "\"Where'd I get the cat? Cards. Poor thing was used in place of coin by some pet-smuggling lowlife. I'm teaching her how to count cards and fetch me a pint.\"—Privateer Mahk",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_rustpeltsabrecat.dds",
                        },
                        [10239] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Mulberry Hermit Crab",
                            ["id"] = 10239,
                            ["furnitureId"] = 8276,
                            ["description"] = "Before the druids, before the coin-barons, before even the noble houses, the hermit crab held dominion over the Systres. Hauling its belongings wherever it travels, its beady eyes give you a look that seems to say, \"We're not so different, you and I.\"",
                            ["hint"] = "Awarded by earning the \"Lost Depths Explorer\" achievement.",
                            ["icon"] = "/esoui/art/icons/pet_damsonhermitcrab.dds",
                        },
                        [10238] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Morthal Bear-Dog",
                            ["id"] = 10238,
                            ["furnitureId"] = 8275,
                            ["description"] = "It's the prestige of the mastiffs of Morthal that give the city's resident breed of bear-dog license to be a bit more … silly. Whether watching over children or facing intruders, someone's bound to get a licking.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_spottedbeardog.dds",
                        },
                        [10237] = 
                        {
                            ["category"] = "Canines",
                            ["name"] = "Warmaiden's Wolf",
                            ["id"] = 10237,
                            ["furnitureId"] = 8274,
                            ["description"] = "While Nords claim this lightning-limned wolf seeks out Kyne's champions to serve, the Stonelore Druids believe differently. Only an imbalance in nature would cause such a creature to coalesce. Its purpose? To find a rider who can restore the balance.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_handmaidensstormwolf.dds",
                        },
                        [7110] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Emberthroat Durzog",
                            ["id"] = 7110,
                            ["furnitureId"] = 6541,
                            ["description"] = "Bred for their wicked intelligence, the Emberthroat Durzog might just outwit the Netch Gouger Goblins that raised them. Only those with nimbler minds keep their loyalty—and that might just be you!",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_durzogemberthroat.dds",
                        },
                        [7272] = 
                        {
                            ["category"] = "Daedric",
                            ["name"] = "Wickerfright Banekin",
                            ["id"] = 7272,
                            ["furnitureId"] = 6552,
                            ["description"] = "\"Witches refused to share the grisly secrets of the Wickerfright summoning ritual … until now. Upon appearing, its wooden countenance twists into an eerie smile—a frightful expression, indeed!\"—Warlock Aldaale",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_wickerfrightbanekin.dds",
                        },
                        [7506] = 
                        {
                            ["category"] = "General",
                            ["name"] = "Statuette: Auri-El, Aldmer King",
                            ["id"] = 7506,
                            ["furnitureId"] = 6638,
                            ["description"] = "A miniature statue of Auri-El, chief deity of the Aldmeri pantheon, with an eagle.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/housing_ayl_run_dbhstatuegarlasmalatarsmall001.dds",
                        },
                        [6406] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "New Moon Senche",
                            ["id"] = 6406,
                            ["furnitureId"] = 5978,
                            ["description"] = "\"Senche steeds are already quiet. This one? It  moves as if it is the avatar of silence.\"—Jonnet of the Sunwalkers",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_newmoonsenche.dds",
                        },
                        [6404] = 
                        {
                            ["category"] = "Camelids",
                            ["name"] = "New Moon Camel",
                            ["id"] = 6404,
                            ["furnitureId"] = 5976,
                            ["description"] = "\"Those seeking their way on dark sands should consider the New Moon Camel. Some say it feeds off the night itself. I say maybe so.\"—Jonnet of the Sunwalkers",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_newmooncamel.dds",
                        },
                        [102] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Doom Wolf Pup",
                            ["id"] = 102,
                            ["furnitureId"] = 4187,
                            ["description"] = "When a Doom Wolf Pup looks at you with its big red eyes, you may just melt inside—but as soon as you turn your back, that little rascal will be shredding your embroidered Arenthian pillows and digging up your herbal garden.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_082.dds",
                        },
                        [618] = 
                        {
                            ["category"] = "Hair Styles",
                            ["name"] = "Pact Lizard Battle Crest",
                            ["id"] = 618,
                            ["furnitureId"] = 4303,
                            ["description"] = "Going to war may mean donning a helm, but beneath it an Argonian Pact warrior is entitled to wear this official Alliance Battle Crest, which keeps spines under control while still looking superb.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/hair_unisex_argonian_ebonheartflavor_01.dds",
                        },
                        [4671] = 
                        {
                            ["category"] = "Ursines",
                            ["name"] = "Frostbane Bear",
                            ["id"] = 4671,
                            ["furnitureId"] = 4768,
                            ["description"] = "The Bear was also one of the ancient Atmoran animal tokens, associated later with the Nord god Tsun, so the Frostbane Bear has historically been one of the most prestigious mounts a tradition-loving Nord could ride.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mounticon_bear_scalecaller.dds",
                        },
                        [8457] = 
                        {
                            ["category"] = "Bipedals",
                            ["name"] = "Nenalata Ayleid Guar",
                            ["id"] = 8457,
                            ["furnitureId"] = 7267,
                            ["description"] = "\"While resting during their evacuation from Nenalata, guar mounts would voluntarily form a circle around the young and infirm, protecting them from danger. Their leader, Mafrelatta, set her calves amid them to share warmth.\"—Beredalmo the Signifier",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_ayleidguar.dds",
                        },
                        [484] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Dwarven War Dog",
                            ["id"] = 484,
                            ["furnitureId"] = 4295,
                            ["description"] = "This loyal beast has been trained for warfare, and will stick with you through every kind of conflict. As a bonus, it comes outfitted in ancient Dwarven dog armor, canine barding as durable today as it was when it was first made many centuries in the past.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_127.dds",
                        },
                        [483] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Dark Moons Lynx",
                            ["id"] = 483,
                            ["furnitureId"] = 4294,
                            ["description"] = "The Khajiit of Corinthe believe the all-black Dark Moons Lynx is the worldly incarnation of Southpaw, the feline companion to Rajhin the Footpad, god of thieves. It's said Southpaw keeps watch while Rajhin is breaking and entering.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_074.dds",
                        },
                        [478] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Infernal Sep Adder",
                            ["id"] = 478,
                            ["furnitureId"] = 4293,
                            ["description"] = "Though it may look like it just crawled from the depths of the Deadlands, the Infernal Sep Adder is actually native to the higher altitudes of Hammerfell. As pets, they are … not affectionate. Great conversation starters, though.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_077.dds",
                        },
                        [10209] = 
                        {
                            ["category"] = "Domestic",
                            ["name"] = "Mottled Sheep",
                            ["id"] = 10209,
                            ["furnitureId"] = 8259,
                            ["description"] = "\"Her calm presence keeps our patients at ease. Sometimes I ask them about the patterns and shapes they see in her coat, and their answers give me insight into their state of mind.\"—Mender Teliel",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_mottledsheep.dds",
                        },
                        [10208] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Glimmertarn Ursauk",
                            ["id"] = 10208,
                            ["furnitureId"] = 8258,
                            ["description"] = "\"We choose some of our guardians based on their overwhelming presence, like this ursauk. While riding it, I swear that the marrow in my bones resonates with her growls.\"—Rolmanoril of Glimmertarn",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_glistergloambear.dds",
                        },
                        [10207] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Harvestleaf Lynx",
                            ["id"] = 10207,
                            ["furnitureId"] = 8257,
                            ["description"] = "\"When trees shrug off their colorful mantles, druids gather around a lynx summoned by Y'ffre. While they sing chants, the God of Song and Forest transforms the feline into a steed. Only a Hearthfire champion may claim such a mount.\"—Book of the Leaves",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_hearthfirelynx.dds",
                        },
                        [10206] = 
                        {
                            ["category"] = "Cervines",
                            ["name"] = "Oldefire Elk",
                            ["id"] = 10206,
                            ["furnitureId"] = 8256,
                            ["description"] = "\"On the first night of Hearthfire, folks all over the Systres burn blessed oldefire logs. The smoke mingles with the soughing of leaves, giving form to spirits unseen the rest of the year. They take the form of loyal elk steeds.\"—Book of the Leaves",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_fireleafelk.dds",
                        },
                        [11959] = 
                        {
                            ["category"] = "Multi-Rider",
                            ["name"] = "Dark Brotherhood Crew Steed",
                            ["id"] = 11959,
                            ["furnitureId"] = 9616,
                            ["description"] = "The steeds of the Dark Brotherhood are conditioned to run blindly ahead in the darkness, fully trusting their riders. When the situation demands it, the horses will even run with multiple riders clinging to them on all sides, never flinching or faltering.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhoodtandemsteed.dds",
                        },
                        [11960] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Dark Brotherhood Sabre Cat",
                            ["id"] = 11960,
                            ["furnitureId"] = 9617,
                            ["description"] = "Few creatures are more apt mounts for the Dark Brotherhood than sabre cats. Light on their feet, agile, and with a hunting instinct to match their rider's, many Dark Brotherhood members believe a sabre cat mount is a gift from Sithis himself.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhoodsabrecat.dds",
                        },
                        [11961] = 
                        {
                            ["category"] = "Bipedals",
                            ["name"] = "Dark Brotherhood Kagouti",
                            ["id"] = 11961,
                            ["furnitureId"] = 9618,
                            ["description"] = "\"Sithis teaches silence, yes, but stealth is not always the most important thing when you have enough speed and power on your side. That's why I choose to ride a kagouti. I find their ferocity more than makes up for the noise.\"—Dark Brother Bols Uveleth",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhoodkagouti.dds",
                        },
                        [11962] = 
                        {
                            ["category"] = "Canines",
                            ["name"] = "Dark Brotherhood Durzog",
                            ["id"] = 11962,
                            ["furnitureId"] = 9619,
                            ["description"] = "Unlike other durzogs, which can become vocal when they sense their prey is near, those trained by the Dark Brotherhood have been bred for speed and silence.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhooddurzog.dds",
                        },
                        [10201] = 
                        {
                            ["category"] = "Ursines",
                            ["name"] = "Stonelore Bear",
                            ["id"] = 10201,
                            ["furnitureId"] = 8251,
                            ["description"] = "Each of the druid circles keeps a different ursine companion. The Stonelore bear was originally bred to help with ambitious construction projects. While druids shaped heavy stone slabs, their bears supported the more fragile components of the structures.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_stonelorebear.dds",
                        },
                        [10199] = 
                        {
                            ["category"] = "Heavyweights",
                            ["name"] = "Druid-Bound Ursauk",
                            ["id"] = 10199,
                            ["furnitureId"] = 8249,
                            ["description"] = "\"I prefer the company of animals over people. Communing with the Evergrowth provides a calming respite from the need to speak. This ursauk, for example, has proven most personable. And now, it needs a rider.\"—Druid Dolvasie",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_monsterousbear.dds",
                        },
                        [1392] = 
                        {
                            ["category"] = "Camelids",
                            ["name"] = "Flame Atronach Camel",
                            ["id"] = 1392,
                            ["furnitureId"] = 4474,
                            ["description"] = "When Peregrine Direnni passed her Master Conjurer test by summoning the first-ever Flame Atronach Camel, her mentor Corvus gave her high marks but was heard to comment, \"Now you're just showing off.\"",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mounticon_atronachcamel_a.dds",
                        },
                        [1387] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Shadowghost Pack Wolf",
                            ["id"] = 1387,
                            ["furnitureId"] = 4473,
                            ["description"] = "Unlike their lone cousins, the great Shadowghost Wolf Mounts, the smaller Shadowghost Pack Wolves hunt on the darkest nights in howling groups. Separated from their packs, they make loyal companions.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_151.dds",
                        },
                        [1380] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Clockwork Skeevaton",
                            ["id"] = 1380,
                            ["furnitureId"] = 4471,
                            ["description"] = "Originally designed for probing tiny, inaccessible areas of the Clockwork City, the mechanical Skeevaton can be set to recognize and follow an individual mortal, replicating pet behavior on the surface of Nirn.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pat_153.dds",
                        },
                        [10182] = 
                        {
                            ["category"] = "General",
                            ["name"] = "Statuette: Mehrunes Dagon",
                            ["id"] = 10182,
                            ["furnitureId"] = 8197,
                            ["description"] = "A miniature statue of Mehrunes Dagon, Daedric Prince of Destruction and Ambition.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettedagon001.dds",
                        },
                        [10181] = 
                        {
                            ["category"] = "General",
                            ["name"] = "Statuette: Kaladas of Leyawiin",
                            ["id"] = 10181,
                            ["furnitureId"] = 8196,
                            ["description"] = "A miniature statue of Saint Kaladas, builder of the Great Chapel of Zenithar in Leyawiin.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettestkaladas001.dds",
                        },
                        [10065] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Aurulun Fledgling Gryphon",
                            ["id"] = 10065,
                            ["furnitureId"] = 8195,
                            ["description"] = "Spring blossoms nod their heads as if recognizing kin in this Elf-pampered companion. Some caretakers claim these gryphons provide a sense of ease to those who care for them—and pain for those who seek their demise.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_aurulungryphon.dds",
                        },
                        [1147] = 
                        {
