                        [9977] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Aurora Firepot Spider",
                            ["id"] = 9977,
                            ["furnitureId"] = 8067,
                            ["description"] = "Feeling festive? Let this little firepot spider follow you around! With its adorable alchemical light show, you're bound to brighten up anyone's day—including your own!",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_aurorafirepotspider.dds",
                        },
                        [9978] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Salamandrine Pony Guar",
                            ["id"] = 9978,
                            ["furnitureId"] = 8068,
                            ["description"] = "\"To my chagrin, thieves stole my current batch of pony guars! I'd hoped to gift some to my cousin, who adored my salamandrine guar and whose love of pony guars knows no bounds. Those thieves had better watch out.\"—Irastimil Direnni, Creature Creator",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_salamanderponyguar.dds",
                        },
                        [7931] = 
                        {
                            ["category"] = "Houseguests",
                            ["name"] = "Biro-dar",
                            ["id"] = 7931,
                            ["furnitureId"] = 6742,
                            ["description"] = "Don't let Biro-dar's appearance deceive you! He's not your average scholar. In fact, he makes for an entertaining and trouble-prone guest. After adding Biro-dar to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/assistant_birodar.dds",
                        },
                        [9980] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Tortoiseshell Echatere",
                            ["id"] = 9980,
                            ["furnitureId"] = 8070,
                            ["description"] = "While they often disagree on theology, the Orsinium Orcs are unified by their love of this echatere's coat. Some call it a blessing from Trinimac. Others call it an outcast's brand from Malacath. Either way, this beast is a bundle of skittering joy.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_spottedechalette.dds",
                        },
                        [9981] = 
                        {
                            ["category"] = "Bipedals",
                            ["name"] = "Spellscar Kagouti",
                            ["id"] = 9981,
                            ["furnitureId"] = 8071,
                            ["description"] = "Driven to madness by the erratic magic around the Spellscar, these kagouti make surprisingly excellent pets. In comparison to their lucid and more aggressive kin, an insane kagouti is docile and picks up commands with ease.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_spellscarkagouti.dds",
                        },
                        [9982] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Wraithtide Senche",
                            ["id"] = 9982,
                            ["furnitureId"] = 8072,
                            ["description"] = "\"Some believe these skeletal senche respond to the call of a lost soul seeking safe passage. I firmly believe Y'ffre's hand is involved, and I pray I can prove it one day.\"—Druid Phillic",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntsenche.dds",
                        },
                        [9983] = 
                        {
                            ["category"] = "Equines",
                            ["name"] = "Wraithtide Horse",
                            ["id"] = 9983,
                            ["furnitureId"] = 8073,
                            ["description"] = "\"The day a Stonelore druid thundered in on this frightful sea-birthed horse, well … let's just say I'm glad I recognized Druid Dolvasie on top. Her ferocious expression will haunt my nightmares—as will this steed.\"—Squire Hareld, Oaken Order",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_wraithhaunthorse.dds",
                        },
                        [9984] = 
                        {
                            ["category"] = "Bipedals",
                            ["name"] = "Wraithtide Guar",
                            ["id"] = 9984,
                            ["furnitureId"] = 8074,
                            ["description"] = "\"The ghost of Ol' Brineburr herds glowing guar down trade roads, seeking buyers. Don't be put off by their appearance. Or, hmmm, maybe seeing your steed's skeleton is a bonus to you? Regardless, get one.\"—Initiate Rogeric",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntguar.dds",
                        },
                        [9985] = 
                        {
                            ["category"] = "Ursines",
                            ["name"] = "Wraithtide Bear",
                            ["id"] = 9985,
                            ["furnitureId"] = 8075,
                            ["description"] = "\"Where mages born from water gather, they enact ancient rites. Together they bind the essence of bear and sea and death, forming it into a mount one of their number may ride. Or so the tales go.\"—Druid Sandire",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntbear.dds",
                        },
                        [9986] = 
                        {
                            ["category"] = "Canines",
                            ["name"] = "Wraithtide Wolf",
                            ["id"] = 9986,
                            ["furnitureId"] = 8076,
                            ["description"] = "\"Communing with the Evergrowth is sometimes confusing. I saw the waters birth an unusual wolf pack, flowing like the angry waves that gave them life. Experience proves they possess the same loyalty other wolves have toward their riders.\"—Druid Anotille",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntwolf.dds",
                        },
                        [9683] = 
                        {
                            ["category"] = "Ursines",
                            ["name"] = "Wealdspirit Bear",
                            ["id"] = 9683,
                            ["furnitureId"] = 7927,
                            ["description"] = "\"A whole bear? You grew a whole bear? Well? What are you doing with it still? Get out there! Burn a fort to the ground! Make it hit some rocks with its paws! Bask in bear-y devastation!\"—Glooredel, Vinedusk Ranger",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_vineduskbear.dds",
                        },
                        [9678] = 
                        {
                            ["category"] = "Bipedals",
                            ["name"] = "Soulrazer Guar",
                            ["id"] = 9678,
                            ["furnitureId"] = 7924,
                            ["description"] = "The crypts of High Isle are littered with walking suits of armor. Those who survive say that the armor protects treasures of old. But I suspect they haunt the black hallways, waiting for the dead to wake.\"—Grod, Castle Navire Crypt Keeper",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_soulrazerguar.dds",
                        },
                        [9677] = 
                        {
                            ["category"] = "Ursines",
                            ["name"] = "Soulrazer Bear",
                            ["id"] = 9677,
                            ["furnitureId"] = 7923,
                            ["description"] = "\"We know that a crazed necromancer forged these creatures with his dying breath. They are unrelenting, and never stop even when the Ritemaster commands them. Inexplicably, some of the bears sit calmly at the feet of the apprentices.\"—Yrssin, Psijic Order",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_soulrazerbear.dds",
                        },
                        [9676] = 
                        {
                            ["category"] = "Felines",
                            ["name"] = "Soulrazer Senche",
                            ["id"] = 9676,
                            ["furnitureId"] = 7922,
                            ["description"] = "Plates of armor hover around the nonexistent fur of a blue senche. It makes no noise—does not growl or roar with the thrill of the chase. It creeps across the ground slowly, knowing that no prey can escape once the hunt has begun.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_soulrazersenche.dds",
                        },
                        [9645] = 
                        {
