                        [5179] = 
                        {
                            ["category"] = "Constructs",
                            ["name"] = "Ebon Steel Dwarven Spider",
                            ["id"] = 5179,
                            ["furnitureId"] = 5519,
                            ["description"] = "Though Dwarven Metal was usually employed in building Spider constructs, for reasons unknown some rare variants were built with a darker Ebon Steel alloy. When found in working order, these automata are prized by collectors.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_spider_ebonyyellow.dds",
