                        [5180] = 
                        {
                            ["category"] = "Exotic",
                            ["name"] = "Solar Arc Dwarven Spider",
                            ["id"] = 5180,
                            ["furnitureId"] = 5509,
                            ["description"] = "This extremely rare Dwarven Spider model is surmounted with a double golden crescent, interpreted by scholars of the Dwemer as a \"Solar Arc,\" or tribute to the sun—an iconography otherwise completely unknown among the handiworks of the Deep Elves.",
                            ["hint"] = "",
