                        [6459] = 
                        {
                            ["category"] = "Canines",
                            ["name"] = "Oak-Ember Forge Wolf",
                            ["id"] = 6459,
                            ["furnitureId"] = 6006,
                            ["description"] = "A young blacksmith raised a foundling wolf decades ago, thus training the first of the Oak-Ember Forge Wolves as a steed. With its unusual fur pattern, you're sure to make an impression on those around you.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/pet_oakemberforgewolf.dds",
