                            ["category"] = "Felines",
                            ["name"] = "Kynbound Senche-Panther",
                            ["id"] = 6464,
                            ["furnitureId"] = 6011,
                            ["description"] = "Known as steeds of the Dremora, Kynbound Senche-Panthers have found their way into service as mounts for those who have some ties to the Dremora. Perhaps that's you?",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/mount_sanguivorianhowler.dds",
                        },
                        [8096] = 
                        {
                            ["category"] = "Houseguests",
                            ["name"] = "Sister Gellenna",
                            ["id"] = 8096,
                            ["furnitureId"] = 6830,
                            ["description"] = "Gellena left the Icereach Coven to see firsthand what they loathed about other cultures—and to consider what scores she needs to settle. After adding Gellena to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["hint"] = "",
                            ["icon"] = "/esoui/art/icons/assistant_gellenna.dds",
