                            ["category"] = "Conservatory",
                            ["name"] = "Crystalline Mind Barrier, Replica",
                            ["subcategory"] = "Boulders and Large Rocks",
                            ["tags"] = "Interactable",
                            ["description"] = "Replicated painstakingly via rough description by the very few that have returned from the nightmare realms of Vaermina, this barrier is a reminder of a dark and challenging mind-realm far from the light of day.",
                            ["id"] = 197716,
                            ["quality"] = "Epic",
                            ["icon"] = "/esoui/art/icons/housing_uni_str_crystalmindwall001.dds",
                        },
