                            ["quality"] = "Legendary",
                            ["icon"] = "/esoui/art/icons/housing_skr_inc_voidpocketshard001.dds",
                        },
                        [171395] = 
                        {
                            ["category"] = "Workshop",
                            ["name"] = "Dwarven Beacon, Aetheric",
                            ["id"] = 171395,
                            ["description"] = "\"By Dagon's fiery arse, the aetheric stones in this Dwarven device simply will not budge. What are they for? Don't care. But by Zen, I can't lug this entire piece of metal out of here right now. Feh.\"—Gorthuth, Dwarven Ruins Delver",
                            ["subcategory"] = "Machinery",
                            ["quality"] = "Legendary",
                            ["icon"] = "/esoui/art/icons/housing_skr_lsb_markaethericbeacon001.dds",
                        },
                        [171396] = 
